def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    if N == 0:
        return 0

    n = len(grid_values)
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    for i in range(1, n + 1):
        x, y, val = grid_values[i - 1]
        if x == 0 and y == 0:
            continue
        top = dp[x - 1][y] if x > 0 else 0
        left = dp[x][y - 1] if y > 0 else 0
        dp[x][y] = val + max(top, left)

    max_val = 0
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            max_val = max(max_val, dp[i][j])

    return max_val

