def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    if N <= 1:
        return 0

    # Extract the id of the last value in the grid
    last_value_id = grid_values[-1][0]

    # Initialize a 2D list to store the maximum values for each position on the grid
    dp_table = [[0 for _ in range(N)] for _ in range(N)]

    # Fill the dp table
    for row in range(N):
        for col in range(N):
            if row == 0 and col == 0:
                dp_table[row][col] = grid_values[0][2]
            elif row == 0:
                dp_table[row][col] = dp_table[row][col-1] + grid_values[row][2]
            elif col == 0:
                dp_table[row][col] = dp_table[row-1][col] + grid_values[row][2]
            else:
                path1_value = dp_table[row-1][col] + grid_values[row][2]
                path2_value = dp_table[row][col-1] + grid_values[row][2]
                dp_table[row][col] = max(path1_value, path2_value)

    # If it is possible to collect all values in the last row or column
    max_value_on_path2 = 0
    for _ in range(N):
        max_value_on_path2 = max(max_value_on_path2, dp_table[last_value_id][_])
    for _ in range(N):
        max_value_on_path2 = max(max_value_on_path2, dp_table[_][last_value_id])

    # The maximum value on one path can be calculated by finding the maximum value in the dp table
    # and the maximum value ON the second path can be the remaining value
    max_value_path1 = max(dp_table[row][col] for row in range(N) for col in range(N))
    return max_value_path1 + max_value_on_path2

