def mod_inverse(a, b):
    if b == 0:
        return None
    x1, x2, y1, y2 = 1, 0, 0, 1
    while b > 0:
        quotient = a // b
        a, b = b, a % b
        x1, x2 = x2, x1 - quotient * x2
        y1, y2 = y2, y1 - quotient * y2
    if x1 < 0:
        x1 += b
    return x1

